"""Read-only complete-run QA; supports pilot or a screen12 case path."""
from pathlib import Path
import csv,hashlib,json,math,sys
import numpy as np
def readcsv(p):return list(csv.DictReader(p.open()))
def analyze(C):
 C=Path(C);T=C/'runtime';M=json.loads((C/'CASE_META.json').read_text());result=json.loads((C/'RUN_RESULT.json').read_text());out=dict(experiment_identity=M['experiment_identity'],case=M['case'],role=C.name,stop_reason=result.get('resource_stop_reason',result.get('result')),native_goal_count=result.get('native_goal_count',0),official_success=result.get('localization_success',False),independent_randomness_claim=False,new_worlds=0)
 if not(T/'native_posterior_updates.csv').exists():
  out.update(qualification='TECHNICAL_OR_PRE_GOAL_FAILURE_NO_SOURCE_POSTERIOR',official_success=None,error=result.get('error'));(C/'FINAL_RUN_QA.json').write_text(json.dumps(out,indent=2)+'\n');return out
 assert result.get('preflight')=='PASS';p=json.loads((T/'BASELINE_PARAMETER_GATE.json').read_text());assert p['checked']['convergence_thr']==1 and p['checked']['use_sim_time']and not p['checked']['useWindGroundTruth'];exe=json.loads((T/'NATIVE_EXECUTABLE_IDENTITY.json').read_text());assert len(exe)==1 and exe[0]['sha256']=='e63fadfdb5b4b20ea6936f38c3a1d5edf0d1e9e236ed8d78a4846b009aefed78'
 n=json.loads((T/'NAVIGATION_MAP_METADATA.json').read_text());nx,ny=n['width']//25,n['height']//25;cell=np.float32(n['resolution'])*np.float32(25);origin=np.array([n['origin_x'],n['origin_y']],dtype='f4');truth=np.array(M['source_xyz'][:2]);trueidx=((truth-origin.astype('f8'))/float(cell)).astype(int);rows=readcsv(T/'native_posterior_updates.csv');updates=sorted({int(x['update'])for x in rows});summaries=[];scores=readcsv(T/'native_candidate_maps.csv');binary=(T/'native_candidate_maps.f32').read_bytes();maxerr=0.;D=p['checked']['sourceDiscriminationPower']
 for u in updates:
  z=[x for x in rows if int(x['update'])==u];assert len(z)>0;idx=np.array([int(x['col'])+nx*int(x['row'])for x in z]);prob=np.array([float(x['source_probability'])for x in z]);coords=np.array([[float(x['x_m']),float(x['y_m'])]for x in z],dtype='f4');assert np.isfinite(prob).all()and np.all(prob>=0)and abs(prob.sum()-1)<1e-10;mean=(prob@coords).astype('f4');variance=float(prob@np.sum((coords-mean).astype('f8')**2,axis=1));order=sorted(range(len(z)),key=lambda k:(int(z[k]['col']),int(z[k]['row'])));order=sorted(order,key=lambda k:-prob[k]);count=math.ceil(len(z)*.05);best=order[:count];top=(prob[best]@coords[best]/prob[best].sum()).astype('f4');mapidx=order[0];cover=np.cumsum(prob[order]);j=np.searchsorted(cover,.9);cut=prob[order[min(j,len(order)-1)]];true=np.where(idx==int(trueidx[0]+nx*trueidx[1]))[0];truep=float(prob[true[0]])if len(true)else None;rank=int((prob>truep).sum()+1)if truep is not None else None
  a=np.array([float(x['hit_confidence'])for x in z]);lo=np.array([float(x['hit_log_odds'])for x in z]);observed=1-1/(1+np.exp(np.clip(lo,-700,700)));cs=[x for x in scores if int(x['update'])==u];reconstruction=np.zeros(nx*ny)
  for c in sorted(cs,key=lambda x:-int(x['size_x'])*int(x['size_y'])):
   h=np.frombuffer(binary,dtype='<f4',count=int(c['count']),offset=int(c['offset_bytes']));assert len(h)==nx*ny;v=float(np.prod(1-np.abs(observed-h[idx])*D*a));native=float(c['score']);maxerr=max(maxerr,abs(v-native)/max(abs(native),1e-280));x,y,sx,sy=[int(c[k])for k in ['origin_x','origin_y','size_x','size_y']];reconstruction.reshape(ny,nx)[y:y+sy,x:x+sx]=native
  reconstructed=reconstruction[idx];reconstructed/=reconstructed.sum();assert np.max(abs(reconstructed-prob))<1e-10
  summaries.append(dict(update=u,source_cells=len(z),variance_m2=variance,source_supported=bool(len(true)),true_rank=rank,true_probability=truep,true_in_90HPD=bool(truep>=cut)if truep is not None else False,MAP_xy=coords[mapidx].tolist(),MAP_error_m=math.dist(coords[mapidx],truth),Top5_xy=top.tolist(),Top5_error_m=math.dist(top,truth),mean_xy=mean.tolist(),mean_error_m=math.dist(mean,truth)))
 assert maxerr<1e-10;windows=readcsv(T/'native_window_consumption.csv');consumed=[x for x in windows if x['status']=='CONSUMED'];assert all(int(x['gas_count'])>0 and int(x['wind_count'])>0 for x in consumed)
 timeline=readcsv(C/'PHYSICAL_FRAME_TIME.csv');times=np.array([float(x['physical_snapshot_time_s'])for x in timeline]);clock=readcsv(T/'physical_clock_trace.csv');base=times[int(M['player']['initial_iteration'])];residual=[];lag=[]
 for x in clock:
  actual=float(x['target_internal_s']);want=base+(int(x['receipt_ros_ns'])-int(x['anchor_ros_ns']))/1e9;residual.append(abs(actual-want));lag.append(actual-float(x['frame_internal_s']));assert abs(float(x['frame_internal_s'])-times[int(x['frame'])])<1e-7
 assert max(residual)<1e-6 and min(lag)>-1e-6 and max(lag)<max(np.diff(times))+1e-5
 for phase in ['PRE_GRAPH','POST_GRAPH']:assert json.loads((C/phase/'GRAPH_GATE.json').read_text())['status']=='PASS_DOMAIN_GRAPH_VACANT'
 owners=json.loads((C/'PROCESS_OWNERS_AND_MONITOR.json').read_text());assert not owners.get('forced')and all(not x['foreign']and not x['unknown']for x in owners['monitor'])
 if(C/'CPP_READOUT.json').exists():
  cpp=json.loads((C/'CPP_READOUT.json').read_text());assert cpp['update']==updates[-1];assert abs(cpp['o24_variance']-summaries[-1]['variance_m2'])<1e-8;summaries[-1].update(Top5_xy=cpp['o24_top5'],Top5_error_m=math.dist(cpp['o24_top5'],truth),mean_xy=cpp['o24_mean'],mean_error_m=math.dist(cpp['o24_mean'],truth),variance_m2=cpp['o24_variance']);out['terminal_readout_verified_with_frozen_CPP']=True
 native=None
 if (T/'native_results.csv').exists():
  parts=(T/'native_results.csv').read_text().split();failed=parts[0]=='FAILED';parts=parts[1:]if failed else parts;native=list(map(float,parts));assert abs(native[3]-summaries[-1]['Top5_error_m'])<1e-5 and abs(native[5]-summaries[-1]['variance_m2'])<1e-5
  if result.get('localization_success'):assert native[5]<1
 rng=[json.loads(x)for x in(T/'native_rng_states.jsonl').read_text().splitlines()];caches=[dict(file=p.name,sha256=hashlib.sha256(p.read_bytes()).hexdigest())for p in T.glob('native_rng_states.jsonl.cache*.f32')]
 out.update(qualification='PASS_NATIVE_DECLARATION_AND_OFFLINE_REPLAY'if result.get('result')=='NATIVE_ACTION_RETURNED'else'PASS_REPLAY_CENSORED_RUN_NOT_A_DECLARATION',terminal=summaries[-1],source_updates=len(updates),candidate_maps=len(scores),score_max_relative_error=maxerr,official_native_results=native,search_physical_s=native[1]if native else None,search_wall_s=result.get('wall_seconds'),consumed_windows=len(consumed),positive_windows=sum(float(x['concentration_mean_ppm'])>.1 for x in consumed),clock_target_residual_max_s=max(residual),snapshot_lag_max_s=max(lag),RNG_recorded_candidates=len(rng),first_RNG_states=rng[:4],RNG_caches=caches,unknown_RNG_scope='Planner RNG not separately serialized; source forward thread states/caches recorded. No full-process bitwise replay proof.',source_domain_class='LEGAL'if summaries[-1]['source_supported']else'EXCLUDED_DIAGNOSTIC_ONLY',full_worlds_are_existing=True)
 (C/'POSTERIOR_UPDATE_METRICS.json').write_text(json.dumps(summaries,indent=2)+'\n');(C/'FINAL_RUN_QA.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n');return out
if __name__=='__main__':
 C=Path(sys.argv[1])if len(sys.argv)>1 else Path(__file__).resolve().parent/'cases/PAPERSTOP_A2_R02';x=analyze(C);print(json.dumps({k:v for k,v in x.items()if k not in ['first_RNG_states','RNG_caches']},ensure_ascii=False,indent=2))
